VALUES ('chal_quiz_webf_111', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-1-1' AND is_deleted = false LIMIT 1), 'landmarks-headings-quiz', 'What does the screen reader list?', 'Two questions from the rebuilt shop page: which elements of a typical article page become landmarks, and what decides the level of a heading.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_111'), 'A screen reader user opens the landmarks list on this page. Which landmarks does it show?

<body>
  <header><a href="/">Trailhead</a></header>
  <nav aria-label="Primary">...</nav>
  <main>
    <article>
      <header><h1>How we test trail shoes</h1></header>
      <section><h2>Lab tests</h2>...</section>
      <footer>Written by Mai Tran</footer>
    </article>
  </main>
  <footer>(c) 2026 Trailhead</footer>
</body>', 'single_choice'::question_type, 'header and footer become banner and contentinfo only when they are not inside article, aside, main, nav or section. The article''s own header and footer are just its introduction and footer, so they are not landmarks. A section is a region landmark only when it has an accessible name (aria-labelledby or aria-label), and this one has none. article is not a landmark at all. That leaves four: the page header (banner), the nav labelled Primary (navigation), main, and the page footer (contentinfo).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('banner, navigation "Primary", main, contentinfo', true),
        ('banner, navigation "Primary", main, banner, region, contentinfo, contentinfo', false),
        ('banner, navigation "Primary", main, region "Lab tests", contentinfo', false),
        ('banner, navigation "Primary", main, article, contentinfo', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_111'), 'Which statements about headings are true in today''s browsers and screen readers? (Select all that apply.)', 'multiple_choice'::question_type, 'The level of a heading comes from its tag, h1 to h6. The HTML "outline algorithm", which would have lowered an h1 nested in sections, was never implemented by browsers and was removed from the HTML standard in 2022, so a nested h1 is still announced as level 1. Choose the level from the structure (a subsection of an h2 section gets an h3) and change the size with CSS; picking h4 for its font size gives screen reader users a false table of contents. WCAG does not require exactly one h1: 1.3.1 and 2.4.6 ask that the structure is programmatically available and that headings describe their content. One h1 that names the page is a strong convention, not a pass/fail rule.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('An h1 inside two nested section elements is announced as a level-3 heading.', false),
        ('The level a screen reader announces comes from the tag name, h1 to h6.', true),
        ('A heading''s level should follow the structure (one more than the section it belongs to), and its size is set with CSS.', true),
        ('Using h4 for a card title is fine when h4 has the right font size for the design.', false),
        ('A page with two h1 elements fails WCAG 2.2.', false)
    ) AS o(option_text, is_correct);

