VALUES ('chal_quiz_webf_121', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-1-2' AND is_deleted = false LIMIT 1), 'form-names-and-errors-quiz', 'Names and errors in the sign-up form', 'Work out what the redesigned sign-up form got wrong about its errors, then predict which of several competing sources gives a field its accessible name.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_121'), 'After a failed submit, the redesigned sign-up form turns the border of each wrong field red. There is no error text anywhere on the page, and the fields have placeholders but no labels. Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'The red border is the only way the form tells anyone which field is wrong, so information is conveyed by colour alone: that fails 1.4.1 Use of Color, and a user who cannot tell red from grey cannot find the field. 3.3.1 Error Identification requires that the field in error is identified and the error is described to the user in text - a border is neither. aria-invalid="true" only exposes an invalid state to assistive technology: sighted users see nothing and nobody learns what is wrong or how to fix it, so on its own it does not meet 3.3.1 (and 3.3.3 Error Suggestion wants the fix described too). Red does not satisfy contrast requirements automatically: a red border is a UI component boundary that needs 3:1 against its neighbours under 1.4.11 Non-text Contrast, and many reds on white pass while others do not - and contrast was never the problem here.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('It fails 1.4.1 Use of Color: colour is the only thing that marks a field as wrong.', true),
        ('It fails 3.3.1 Error Identification: the error is not described to the user in text.', true),
        ('Adding aria-invalid="true" to the red fields is enough to meet 3.3.1, because screen readers then announce the error.', false),
        ('Red borders always meet the contrast requirements, because red is a strong colour.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_121'), 'What is the accessible name of this input?

<h2 id="receipt-title">Where should we send your receipt?</h2>
<label for="receipt-email">Email</label>
<input id="receipt-email" name="email" type="email"
       placeholder="name@example.com"
       aria-label="Your email"
       aria-labelledby="receipt-title">', 'single_choice'::question_type, 'The accessible name comes from the first source that gives text, in this order: aria-labelledby, then aria-label, then the native label (label for="id" or a wrapping label), and only as a last resort title or placeholder. aria-labelledby points at the heading and gives text, so it wins and both the visible label "Email" and the aria-label are ignored. That is why mixing sources is risky: the visible label says "Email" but a screen reader user hears the heading text, and a voice control user who says "click Email" may not reach the field. Use one source, and prefer a visible label.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_121') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Email', false),
        ('Your email', false),
        ('Where should we send your receipt?', true),
        ('name@example.com', false)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_webf_122 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_webf_122', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-1-2' AND is_deleted = false LIMIT 1), 'fix-form-accessible-name-auditor', 'Fix the form auditor', 'auditForm() computes the accessible name and the description (hint and error text) of every control in a form, so the release check can flag fields a screen reader cannot identify. It passed the placeholder-only sign-up form that caused the incident, and on the fixed form it gives fields the wrong label, cuts multi-id names short and drops the error message. Fix it so it follows its contract. Hint: which attribute does label[for] point at, what is a placeholder, and how many ids does an ID list hold?', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
