INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_webf_122'), 'The incident: placeholder-only sign-up fields have no name', '{"controls":[{"id":"f1","type":"email","name":"f1","attrs":{"placeholder":"Email"}},{"id":"f2","type":"password","name":"f2","attrs":{"placeholder":"Password"}},{"id":"f3","type":"text","name":"f3","attrs":{"placeholder":"Full name","title":"Your full name"}}],"labels":[],"text":{}}', '[{"id":"f1","name":"","from":"none","description":""},{"id":"f2","name":"","from":"none","description":""},{"id":"f3","name":"","from":"none","description":""}]', 4, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_webf_122'), 'label[for] matches the control''s id, not its name attribute', '{"controls":[{"id":"signup-email","type":"email","name":"email","attrs":{"autocomplete":"email"}},{"id":"email","type":"email","name":"backup_email","attrs":{}},{"id":"signup-name","type":"text","name":"full_name","attrs":{"autocomplete":"name"}}],"labels":[{"for":"signup-email","text":"Email address"},{"for":"email","text":" Backup email (optional) "},{"for":"signup-name","text":"Full name"}],"text":{}}', '[{"id":"signup-email","name":"Email address","from":"label","description":""},{"id":"email","name":"Backup email (optional)","from":"label","description":""},{"id":"signup-name","name":"Full name","from":"label","description":""}]', 4, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_webf_122'), 'aria-labelledby with several ids joins their texts in list order', '{"controls":[{"id":"phone","type":"tel","name":"phone","attrs":{"aria-labelledby":"phone-label phone-country","autocomplete":"tel"}},{"id":"otp","type":"text","name":"code","attrs":{"aria-labelledby":"otp-title  otp-sent-to","autocomplete":"one-time-code"}}],"labels":[{"for":"phone","text":"Phone"}],"text":{"phone-label":"Phone number","phone-country":"Vietnam (+84)","otp-title":"Verification code","otp-sent-to":"sent to +84 90 123 4567"}}', '[{"id":"phone","name":"Phone number Vietnam (+84)","from":"aria-labelledby","description":""},{"id":"otp","name":"Verification code sent to +84 90 123 4567","from":"aria-labelledby","description":""}]', 3, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_webf_122'), 'aria-describedby links both the hint and the error message', '{"controls":[{"id":"pw","type":"password","name":"password","attrs":{"aria-describedby":"pw-hint pw-error","aria-invalid":"true","autocomplete":"new-password"}},{"id":"signup-email","type":"email","name":"email","attrs":{"aria-describedby":"email-error","aria-invalid":"true","autocomplete":"email"}}],"labels":[{"for":"pw","text":"Create a password"},{"wraps":"signup-email","text":"Email address"}],"text":{"pw-hint":"At least 12 characters.","pw-error":"Error: the password is too short (8 of 12 characters).","email-error":"Error: enter an email address like name@example.com."}}', '[{"id":"pw","name":"Create a password","from":"label","description":"At least 12 characters. Error: the password is too short (8 of 12 characters)."},{"id":"signup-email","name":"Email address","from":"label","description":"Error: enter an email address like name@example.com."}]', 3, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_webf_122'), 'Precedence: aria-labelledby, then aria-label, then the label; wrapping labels count', '{"controls":[{"id":"billing-street","type":"text","name":"street","attrs":{"aria-labelledby":"billing-heading street-label","aria-label":"Address","autocomplete":"billing street-address"}},{"id":"help-search","type":"search","name":"q","attrs":{"aria-label":"Search the help center","placeholder":"Search"}},{"id":"terms","type":"checkbox","name":"terms","attrs":{}},{"id":"plan-free","type":"radio","name":"plan","attrs":{}},{"id":"plan-pro","type":"radio","name":"plan","attrs":{}}],"labels":[{"for":"billing-street","text":"Street"},{"for":"help-search","text":"Search"},{"wraps":"terms","text":"I accept the terms of service"},{"wraps":"plan-free","text":"Free"},{"for":"plan-pro","text":"Pro - 5 USD a month"}],"text":{"billing-heading":"Billing address","street-label":"Street and number"}}', '[{"id":"billing-street","name":"Billing address Street and number","from":"aria-labelledby","description":""},{"id":"help-search","name":"Search the help center","from":"aria-label","description":""},{"id":"terms","name":"I accept the terms of service","from":"label","description":""},{"id":"plan-free","name":"Free","from":"label","description":""},{"id":"plan-pro","name":"Pro - 5 USD a month","from":"label","description":""}]', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_fix_webf_122'), 'Missing ids are skipped, blank values fall through, a placeholder never counts', '{"controls":[{"id":"postal","type":"text","name":"zip","attrs":{"aria-labelledby":"does-not-exist","aria-label":"   ","placeholder":"70000","autocomplete":"postal-code"}},{"id":"dob","type":"date","name":"birthday","attrs":{"aria-describedby":"missing-hint dob-error","aria-invalid":"true","autocomplete":"bday"}},{"id":"full-name","type":"text","name":"name","attrs":{"aria-labelledby":"empty-span name-label"}},{"id":"nickname","type":"text","name":"nickname","attrs":{"placeholder":"What should we call you?","title":"Nickname"}}],"labels":[{"for":"postal","text":"Postal code"},{"wraps":"dob","text":"Date of birth"}],"text":{"dob-error":"Error: enter a date in the past.","empty-span":"  ","name-label":"Full name"}}', '[{"id":"postal","name":"Postal code","from":"label","description":""},{"id":"dob","name":"Date of birth","from":"label","description":"Error: enter a date in the past."},{"id":"full-name","name":"Full name","from":"aria-labelledby","description":""},{"id":"nickname","name":"","from":"none","description":""}]', 3, false, true, 6);
