-- challenge chal_quiz_webf_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_webf_211', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-2-1' AND is_deleted = false LIMIT 1), 'cascade-specificity-layers-quiz', 'Who sets the Pay now background?', 'Two questions from the checkout incident: which of three competing rules wins once the design system moves into a cascade layer, and how specificity is really compared.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_211'), 'The checkout page loads these style sheets, in this order:

/* app.css */
@layer reset, base, components, utilities;
@import url("ds-v4.css") layer(components);

/* inside ds-v4.css */
.btn-primary { background: #1d4ed8; }

/* datepicker.min.css, linked after app.css, not in any layer */
form button { background: #e5e7eb; }

The Pay now button is <button class="btn btn-primary"> inside the checkout <form>, and it is enabled. Which background does it get, and why?', 'single_choice'::question_type, 'Before specificity is ever compared, the cascade sorts by cascade layer. For normal (not !important) declarations, styles that are in no layer beat styles in every layer, whatever their selectors. datepicker.min.css is unlayered and ds-v4.css was imported into the components layer, so form button wins with a specificity of only (0,0,2) against (0,1,0). Specificity only decides between declarations of the same importance in the same layer, and order of appearance only decides when specificity ties too. Before the upgrade, the v3 design system was linked as an unlayered file, both rules were compared by specificity, and .btn-primary won. That is why the button turned grey only after both changes, and only on the page that loads the date picker.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('#1d4ed8 (blue): .btn-primary has specificity (0,1,0), which beats (0,0,2).', false),
        ('#e5e7eb (grey): form button is unlayered, and for normal declarations unlayered styles beat every layer before specificity is compared.', true),
        ('#e5e7eb (grey): form button appears later in the page, and the later declaration always wins.', false),
        ('#1d4ed8 (blue): components is declared after reset and base, and later layers beat everything else.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_211'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'Specificity is a triple (A ids, B classes/attributes/pseudo-classes, C types/pseudo-elements) compared column by column, so one id beats any number of classes: (1,0,0) > (0,11,0). :where() always contributes zero, so :where(#checkout) .btn is just (0,1,0). :is(), :not() and :has() take the specificity of their MOST specific argument, whichever argument actually matched: :is(#pay, .btn) is (1,0,0) even on an element that only has the class. !important does not change specificity at all; it moves the declaration into a different step of the cascade (importance), where it beats every normal declaration. Inside that step the layer order is reversed: an !important declaration in an earlier layer (base) beats an !important declaration in a later layer (components).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('#pay beats a selector made of 11 classes, such as .a.b.c.d.e.f.g.h.i.j.k.', true),
        (':where(#checkout) .btn has specificity (0,1,0).', true),
        (':is(#pay, .btn) counts as (0,1,0) on an element that matched only through .btn.', false),
        ('!important raises a declaration''s specificity above any id.', false),
        ('With @layer base, components; an !important declaration in base beats an !important declaration in components.', true)
    ) AS o(option_text, is_correct);

