INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_212'), 'The incident: unlayered vendor CSS wins, !important beats :disabled, a vendor layer fixes both', '{"cases":[{"layers":["reset","base","components","utilities"],"declarations":[{"selector":".btn-primary","value":"#1d4ed8","layer":"components","important":false},{"selector":"form button","value":"#e5e7eb","layer":null,"important":false}]},{"layers":["reset","base","components","utilities"],"declarations":[{"selector":".btn-primary","value":"#1d4ed8","layer":"components","important":false},{"selector":".btn:disabled","value":"#cbd5e1","layer":"components","important":false},{"selector":"form button","value":"#e5e7eb","layer":null,"important":false},{"selector":".btn-primary","value":"#1d4ed8","layer":null,"important":true}]},{"layers":["reset","vendor","base","components","utilities"],"declarations":[{"selector":"form button","value":"#e5e7eb","layer":"vendor","important":false},{"selector":".btn-primary","value":"#1d4ed8","layer":"components","important":false},{"selector":".btn:disabled","value":"#cbd5e1","layer":"components","important":false}]},{"layers":["reset","vendor","base","components","utilities"],"declarations":[{"selector":"form button","value":"#e5e7eb","layer":"vendor","important":false},{"selector":".btn-primary","value":"#1d4ed8","layer":"components","important":false}]}]}', '[{"index":1,"value":"#e5e7eb","specificity":[0,0,2]},{"index":3,"value":"#1d4ed8","specificity":[0,1,0]},{"index":2,"value":"#cbd5e1","specificity":[0,2,0]},{"index":1,"value":"#1d4ed8","specificity":[0,1,0]}]', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_212'), 'Specificity is compared column by column, never added up as one number', '{"cases":[{"layers":[],"declarations":[{"selector":"#pay","value":"red","layer":null,"important":false},{"selector":".a.b.c.d.e.f.g.h.i.j.k","value":"blue","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":".btn","value":"red","layer":null,"important":false},{"selector":"html body main form div div div div div div button","value":"blue","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":"nav > ul li + li ~ a:focus-visible::after","value":"red","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":"input[type=\"checkbox\"]:checked+label","value":"red","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":"body > * + *","value":"red","layer":null,"important":false}]}]}', '[{"index":0,"value":"red","specificity":[1,0,0]},{"index":0,"value":"red","specificity":[0,1,0]},{"index":0,"value":"red","specificity":[0,1,6]},{"index":0,"value":"red","specificity":[0,2,2]},{"index":0,"value":"red","specificity":[0,0,1]}]', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_212'), ':is(), :not() and :has() count their most specific argument; :where() counts zero', '{"cases":[{"layers":[],"declarations":[{"selector":":where(#checkout) .btn","value":"red","layer":null,"important":false},{"selector":".btn","value":"blue","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":":is(.btn, #pay)","value":"red","layer":null,"important":false},{"selector":".btn.btn-primary","value":"blue","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":"button:not(.ghost,.link)","value":"red","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":"form:has(> button, input[type=\"date\"]) label","value":"red","layer":null,"important":false}]},{"layers":[],"declarations":[{"selector":":where(nav, #menu) a:not(:hover)","value":"red","layer":null,"important":false}]}]}', '[{"index":1,"value":"blue","specificity":[0,1,0]},{"index":0,"value":"red","specificity":[1,0,0]},{"index":0,"value":"red","specificity":[0,1,1]},{"index":0,"value":"red","specificity":[0,1,3]},{"index":0,"value":"red","specificity":[0,1,1]}]', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_212'), 'The style attribute beats every selector of the same importance, but not an !important rule', '{"cases":[{"layers":["base"],"declarations":[{"selector":"#checkout #pay","value":"red","layer":null,"important":false},{"selector":null,"value":"blue","layer":null,"important":false,"inline":true}]},{"layers":["base","components"],"declarations":[{"selector":null,"value":"blue","layer":null,"important":false,"inline":true},{"selector":".btn","value":"red","layer":"components","important":true}]},{"layers":["reset","base"],"declarations":[{"selector":null,"value":"blue","layer":null,"important":true,"inline":true},{"selector":"#pay","value":"red","layer":"reset","important":true}]},{"layers":[],"declarations":[{"selector":null,"value":"green","layer":null,"important":false,"inline":true},{"selector":null,"value":"blue","layer":null,"important":false,"inline":true}]}]}', '[{"index":1,"value":"blue","specificity":null},{"index":1,"value":"red","specificity":[0,1,0]},{"index":0,"value":"blue","specificity":null},{"index":1,"value":"blue","specificity":null}]', 5, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_212'), 'Normal: unlayered beats every layer, later layers beat earlier ones, whatever the specificity', '{"cases":[{"layers":["reset","base","components","utilities"],"declarations":[{"selector":"#pay #pay","value":"red","layer":"base","important":false},{"selector":".btn","value":"blue","layer":"components","important":false}]},{"layers":["reset","base","components","utilities"],"declarations":[{"selector":"button","value":"red","layer":null,"important":false},{"selector":"#pay","value":"blue","layer":"utilities","important":false}]},{"layers":["reset","base","components","utilities"],"declarations":[{"selector":".btn","value":"red","layer":"components","important":false},{"selector":".btn","value":"blue","layer":"components","important":false},{"selector":".btn","value":"green","layer":"base","important":false}]},{"layers":["reset","vendor","base","components","utilities"],"declarations":[{"selector":"form button","value":"#e5e7eb","layer":"vendor","important":false},{"selector":".btn-primary","value":"#1d4ed8","layer":"components","important":false},{"selector":":where(.checkout) .btn-primary:hover","value":"#1e40af","layer":"utilities","important":false},{"selector":".btn:disabled","value":"#cbd5e1","layer":"components","important":false}]}]}', '[{"index":1,"value":"blue","specificity":[0,1,0]},{"index":0,"value":"red","specificity":[0,0,1]},{"index":1,"value":"blue","specificity":[0,1,0]},{"index":2,"value":"#1e40af","specificity":[0,2,0]}]', 5, false, true, 5),
