-- challenge chal_quiz_webf_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_webf_221', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-2-2' AND is_deleted = false LIMIT 1), 'flexbox-grid-layout-quiz', 'Why does the product page scroll sideways?', 'Two questions from the product listing incident: the automatic minimum size that lets one long product name widen a 1fr column, and what the flex shorthand, auto-fit, logical properties and visual reordering really do.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_221'), 'On phones the results area is a grid with grid-template-columns: 1fr inside a 288px-wide container. One product is named PWRBANK20000MAHUSBCPD65WBLACKEDITION (no spaces, no hyphens), and DevTools shows that the product card containing it has a min-content width of 412px. The grid overlay labels the single column 412px, and the page scrolls sideways. Why is the column wider than the container?', 'single_choice'::question_type, '1fr is short for minmax(auto, 1fr). The auto minimum means the track may not become narrower than the minimum contribution of its items, and grid and flex items have min-width: auto, which resolves to their min-content width: the widest piece of content that cannot wrap. A string without spaces or hyphens has no soft wrap opportunity, so its full 412px width is that minimum, and the track grows to 412px even though the container is only 288px. Writing minmax(0, 1fr) (and min-width: 0 on flex items) removes that minimum; overflow-wrap: anywhere then lets the long name wrap. The fr unit does not ignore content, gap is not added to a single column, and percentages are not involved here.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('1fr means minmax(auto, 1fr): the track cannot shrink below its item''s min-content width, and the unbreakable name makes that 412px.', true),
        ('fr units are calculated from the viewport, not from the container, so 1fr can be wider than the container.', false),
        ('The 24px gap is added on both sides of the only column, which pushes it past the container width.', false),
        ('Grid always sizes columns by their max-content width; only Flexbox lets items shrink.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_221'), 'Which of these statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'flex: 1 expands to flex-grow 1, flex-shrink 1 and a flex basis of 0%, so free space is shared equally whatever the content. With repeat(auto-fit, minmax(220px, 1fr)) the empty repeated tracks collapse to 0, so two items in a row with room for five share the whole row; auto-fill would keep the five tracks and leave the empty ones as space. order, grid placement and row-reverse only change where boxes are painted: the Tab sequence and the reading order of a screen reader still follow the DOM, which is why moving things visually can fail 1.3.2 Meaningful Sequence and 2.4.3 Focus Order. margin-inline-start follows the writing direction: it is the left margin in a left-to-right line, but the right margin when dir="rtl".', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('flex: 1 is short for flex-grow: 1, flex-shrink: 1 and flex-basis: 0%.', true),
        ('With repeat(auto-fit, minmax(220px, 1fr)), two items in a row with room for five columns stretch to share the whole row.', true),
        ('order: -1 on a button also moves it earlier in the keyboard Tab order.', false),
        ('flex-direction: row-reverse makes a screen reader read the items from the last one to the first one.', false),
        ('margin-inline-start is always the left margin, whatever the page language.', false)
    ) AS o(option_text, is_correct);

