INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_222'), 'The incident grid: auto-fill, minmax(220px, 1fr), 24px gap at 1200px, 700px and 288px', '{"grids":[{"template":"repeat(auto-fill, minmax(220px, 1fr))","width":1200,"gap":24,"items":12},{"template":"repeat(auto-fill, minmax(220px, 1fr))","width":700,"gap":24,"items":12},{"template":"repeat(auto-fill, minmax(220px, 1fr))","width":288,"gap":24,"items":12}]}', '[[220.8,220.8,220.8,220.8,220.8],[338,338],[288]]', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_222'), 'Fixed and percentage tracks are taken first, then fr tracks share what is left after the gaps', '{"grids":[{"template":"200px 1fr","width":1000,"gap":16,"items":2},{"template":"1fr 2fr 1fr","width":1000,"gap":20,"items":3},{"template":"25% 1fr 100px","width":800,"gap":10,"items":3}]}', '[[200,784],[240,480,240],[200,480,100]]', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_222'), 'Uneven shares are rounded to 2 decimals; decimal percentages work', '{"grids":[{"template":"1fr 1fr 1fr","width":1000,"gap":16,"items":3},{"template":"1fr 2fr","width":1000,"gap":0,"items":2},{"template":"12.5% 1fr 12.5%","width":960,"gap":0,"items":3}]}', '[[322.67,322.67,322.67],[333.33,666.67],[120,720,120]]', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_222'), 'auto-fit collapses empty tracks so the items share the row; auto-fill keeps them', '{"grids":[{"template":"repeat(auto-fill, minmax(220px, 1fr))","width":1200,"gap":24,"items":2},{"template":"repeat(auto-fit, minmax(220px, 1fr))","width":1200,"gap":24,"items":2},{"template":"repeat(auto-fit, minmax(220px, 1fr))","width":1200,"gap":24,"items":7}]}', '[[220.8,220.8,220.8,220.8,220.8],[588,588,0,0,0],[220.8,220.8,220.8,220.8,220.8]]', 5, true, false, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_222'), 'Free space never goes negative: when fixed tracks and gaps fill the container, fr tracks are 0', '{"grids":[{"template":"300px 1fr 300px","width":500,"gap":20,"items":3},{"template":"50% 50% 1fr","width":400,"gap":10,"items":3}]}', '[[300,0,300],[200,200,0]]', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_webf_222'), 'Edge cases: a minimum wider than the container, one item with auto-fit, mixed fr weights', '{"grids":[{"template":"repeat(auto-fill, minmax(220px, 1fr))","width":200,"gap":16,"items":3},{"template":"repeat(auto-fit, minmax(300px, 1fr))","width":1000,"gap":16,"items":1},{"template":"2fr 100px 1fr","width":500,"gap":8,"items":3}]}', '[[220],[1000,0,0],[256,100,128]]', 5, false, true, 6);
