-- challenge chal_quiz_webf_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_webf_311', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-3-1' AND is_deleted = false LIMIT 1), 'contrast-rules-quiz', 'Pass or fail? Reading WCAG contrast results', 'Two decisions from the brand-refresh audit: whether a ratio that displays as almost 4.5:1 passes, and which parts of a form must meet a contrast requirement at all.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_311'), 'The new helper text under the email field is 14px, regular weight, colour #777777 on a #ffffff background. The DevTools colour picker shows a contrast ratio of 4.48. The designer argues: "That rounds to 4.5, so it meets AA." What is the correct verdict for 1.4.3 Contrast (Minimum)?', 'single_choice'::question_type, 'WCAG thresholds are minimums and the ratio is not rounded before comparing: 4.48:1 is below 4.5:1, so the text fails. 14px regular is normal-size text (large text starts at 24px regular or about 18.67px bold), so the 3:1 large-text threshold does not apply, and helper text is not exempt: it is real content that people need to read. The smallest change is a slightly darker grey: #767676 on white is about 4.54:1 and passes.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('It fails: 4.48:1 is below the 4.5:1 minimum, and ratios are not rounded up before the comparison.', true),
        ('It passes: WCAG ratios are compared after rounding to one decimal place.', false),
        ('It passes: helper text only needs 3:1 because it is secondary information.', false),
        ('It fails only AAA (7:1); AA needs 4.5:1 for large text and 3:1 for normal text.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_311'), 'The checkout form has these parts. Under WCAG 2.2 level AA, which of them MUST meet a contrast requirement (1.4.3 for text, 1.4.11 for non-text)? (Select all that apply.)', 'multiple_choice'::question_type, 'Placeholder text is text, and 1.4.3 has no exception for it, so it needs 4.5:1 (better still, do not use it for anything a user must read). When a 1px border is the only thing that shows where a text input is, it is visual information needed to identify the component, so 1.4.11 asks for 3:1 against the adjacent colour. A focus indicator is visual information needed to identify a state, so it is covered by 1.4.11 too. Text in an inactive (disabled) control is explicitly exempt from 1.4.3, and so are logotypes - the text inside the shop''s logo has no contrast requirement.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The grey placeholder text "name@example.com" inside the email field', true),
        ('The 1px border that is the only visual sign of where the email field is', true),
        ('The outline drawn around the Checkout button when it has keyboard focus', true),
        ('The label of the "Place order" button while it is disabled', false),
        ('The shop''s name inside its logo in the header', false)
    ) AS o(option_text, is_correct);

