-- challenge chal_quiz_webf_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_webf_321', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-3-2' AND is_deleted = false LIMIT 1), 'keyboard-access-focus-quiz', 'Keyboard access: buttons, focus rings and dialogs', 'The checkout''s "Apply coupon" control got a quick fix, and the team is arguing about focus styles and the coupon dialog. Decide what still fails for keyboard users and which statements about focus are true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_321'), 'A developer "fixes" the coupon control like this:

<div class="btn" role="button" tabindex="0" onclick="applyCoupon()">Apply coupon</div>

A keyboard-only customer tabs to it. What happens, and why?', 'single_choice'::question_type, 'tabindex="0" puts the div in the Tab sequence and role="button" makes screen readers announce it as a button, so focus and the announced role are fixed. But a click event fires from the keyboard only on elements whose activation behaviour does it: a native <button> turns Enter and Space into a click, a <div> does not, whatever its role. The customer reaches the control and a screen reader would announce "Apply coupon, button", but pressing Enter or Space does nothing (Space even scrolls the page). You would have to add a keydown handler for both keys, prevent the scroll, and handle a disabled state yourself. <button type="button"> gives you all of that for free.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('It works like a button now: tabindex="0" makes it focusable and role="button" makes Enter and Space trigger onclick.', false),
        ('It still cannot receive focus, because only native controls can be focused, whatever their tabindex.', false),
        ('It receives focus and is announced as a button, but Enter and Space do nothing (Space scrolls the page), because only native buttons turn those keys into a click.', true),
        ('It receives focus, but screen readers announce it as "group", because role="button" is ignored on a div.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_321'), 'Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'A global outline: none with no replacement removes the only visible focus indicator, which fails 2.4.7 Focus Visible (AA); style :focus-visible instead of hiding focus. A modal opened with dialog.showModal() makes everything outside the dialog inert, and pressing Escape closes it. Positive tabindex is an anti-pattern: it pulls elements ahead of everything else on the page, so focus no longer follows the reading order (2.4.3 Focus Order) and every element added later without a tabindex ends up behind all of them. 2.4.11 Focus Not Obscured (Minimum, AA) only requires that the focused element is not ENTIRELY hidden by author content such as a sticky header; "no part hidden" is the AAA criterion 2.4.12 Focus Not Obscured (Enhanced).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('*:focus { outline: none } with no other focus style fails 2.4.7 Focus Visible.', true),
        ('A dialog opened with showModal() makes the rest of the page inert, and pressing Escape closes it.', true),
        ('tabindex="1" on the most important field is the recommended way to let keyboard users reach it first.', false),
        ('2.4.11 Focus Not Obscured (Minimum) fails as soon as any part of the focused element is covered by a sticky header.', false)
    ) AS o(option_text, is_correct);

