-- challenge chal_quiz_webf_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_webf_331', (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'web-foundations-html-css-a11y') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-webf-3-3' AND is_deleted = false LIMIT 1), 'images-loading-alt-quiz', 'Fix the hero, label the link', 'Two decisions from the landing page incident: which changes to the hero <img> improve LCP or CLS, and what the alt text of an image-only link should say.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_331'), 'On mobile, this hero image is the LCP element:

<img src="/img/hero-spring.jpg" loading="lazy" alt="Hiker on a ridge at sunrise">

The file is a 2400 px wide JPEG (4:3) shown 390 CSS px wide, and the CSS only sets width: 100%. Which changes improve LCP or CLS for this image? (Select all that apply.)', 'multiple_choice'::question_type, 'loading="lazy" makes the browser wait until layout tells it the image is near the viewport, so the most important image of the page starts downloading late; remove it from anything visible on the first screen. width and height attributes give the browser the aspect ratio before a single byte arrives, so with height: auto the box is reserved and nothing below it moves (CLS). fetchpriority="high" is a hint that moves the hero ahead of other images in the queue. srcset with w descriptors plus sizes lets the browser pick a much smaller candidate for a 390 px slot instead of a 2400 px file. decoding="async" only affects how the downloaded image is decoded; it does not start or speed up the download. And fetchpriority does not cancel loading="lazy": a lazy image is still deferred until layout, whatever its priority.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Remove loading="lazy", so the request can start as soon as the browser finds the <img> in the HTML.', true),
        ('Add width="1600" height="1200" and set height: auto in CSS, so the browser reserves a 4:3 box before the file arrives.', true),
        ('Add fetchpriority="high".', true),
        ('Offer several widths with srcset (w descriptors) and a sizes attribute, so the phone can pick a much smaller file.', true),
        ('Add decoding="async", so the file downloads in parallel with the CSS.', false),
        ('Keep loading="lazy" and add fetchpriority="high": a high priority cancels the lazy delay.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_331'), 'The header has an icon-only link to the shopping cart. There is no other text inside the link:

<a href="/cart"><img src="/img/icons/cart.svg" alt="?" width="24" height="24"></a>

Which alt text is best?', 'single_choice'::question_type, 'This is a functional image: it is the only content of a link, so its alt text becomes the link''s accessible name and must say what the link does or where it goes - "Cart" (WCAG 2.2, 1.1.1 Non-text Content and 2.4.4 Link Purpose). alt="" would be right for a purely decorative image, but here it leaves the link with no name at all, so a screen reader announces only "link" or reads the URL. A description of the drawing ("black outline of a trolley") describes the picture, not the purpose, and "icon" is noise. "image" says nothing. "Click here to go to the cart page" names the destination but adds words that do not help: screen readers already say "link", and not everyone clicks.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_webf_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('alt="Cart"', true),
        ('alt="" - it is just an icon, so it is decorative', false),
        ('alt="Shopping cart icon: a black outline of a trolley"', false),
        ('alt="image"', false),
        ('alt="Click here to go to the cart page"', false)
    ) AS o(option_text, is_correct);

